public function emitirFactura(array $data): Dte
{
    $folio = Dte::where('company_id', $data['company_id'])->max('folio') + 1;
    $dte = Dte::create([...$data, 'folio' => $folio]);
    foreach ($data['lines'] as $line) {
        DteLine::create([...$line, 'dte_id' => $dte->id]);
    }
    Storage::disk('local')->put("dtes/{$folio}.xml", $this->buildXml($dte));
    Mail::to($data['email'])->send(new DteEmitido($dte));
    return $dte;
}

